/*===========================================================================
FUNCTION tdsrrcllc_update_state_indicator_in_oc
DESCRIPTION
This function updates the state indicator in oc using state indicator received 
in reconfig message. if the current state is cell-DCH then keep the state 
indicator  in oc as cell-DCH to store DCH related IEs

DEPENDENCIES
  None.

RETURN VALUE
  SUCCESS or FAILURE
===========================================================================*/
static uecomdef_status_e_type tdsrrcllc_update_state_indicator_in_oc
(
  tdsrrc_RRC_StateIndicator rcvd_state_indicator
)
{
  /* Get the RRC State Indicator */
  switch(rcvd_state_indicator)
  {
  case tdsrrc_RRC_StateIndicator_cell_DCH:
    tdsordered_config_ptr->rrc_state_indicator = TDSRRC_STATE_CELL_DCH;
    break;
    
  case tdsrrc_RRC_StateIndicator_cell_FACH:
  /* If the next state is CELL_FACH while the current state is CELL_DCH, 
  * keep the next state as CELL_DCH so as to process all IEs applicable
  * to CELL_DCH here.
    */
    if(tdscurrent_config_ptr->rrc_state_indicator == TDSRRC_STATE_CELL_DCH)
    {
      tdsordered_config_ptr->rrc_state_indicator = TDSRRC_STATE_CELL_DCH;
    }
    else
    {
      tdsordered_config_ptr->rrc_state_indicator = TDSRRC_STATE_CELL_FACH;
    }

    break;
    
  case tdsrrc_RRC_StateIndicator_cell_PCH:
  /* If the next state is CELL_PCH while the current state is CELL_DCH, 
  * keep the next state as CELL_DCH so as to process all IEs applicable
  * to CELL_DCH here.
    */
    if(tdscurrent_config_ptr->rrc_state_indicator == TDSRRC_STATE_CELL_DCH)
    {
      tdsordered_config_ptr->rrc_state_indicator = TDSRRC_STATE_CELL_DCH;
    }
    else
    {
      tdsordered_config_ptr->rrc_state_indicator = TDSRRC_STATE_CELL_PCH;
    }
    break;

  case tdsrrc_RRC_StateIndicator_ura_PCH:
  /* If the next state is URA_PCH while the current state is CELL_DCH, 
  * keep the next state as CELL_DCH so as to process all IEs applicable
  * to CELL_DCH here.
    */
    if(tdscurrent_config_ptr->rrc_state_indicator == TDSRRC_STATE_CELL_DCH)
    {
      tdsordered_config_ptr->rrc_state_indicator = TDSRRC_STATE_CELL_DCH;
    }
    else
    {
      tdsordered_config_ptr->rrc_state_indicator = TDSRRC_STATE_URA_PCH;
    }
    break;
    
  default:
    TDSRRC_MSG1(MSG_LEGACY_ERROR,"RRC State %d not supported",rcvd_state_indicator);
    return FAILURE;
  } /* End RRC State indicator */

  return SUCCESS;
}

/*===========================================================================
FUNCTION tdsrrcllc_update_urnti_in_oc
DESCRIPTION
This function updates the U-RNTI received in any reconfig message in 
tdsordered_config

DEPENDENCIES
  None.

RETURN VALUE
  SUCCESS or FAILURE
===========================================================================*/
static uecomdef_status_e_type tdsrrcllc_update_urnti_in_oc
(
  uint32 urnti,
  tdsrrc_U_RNTI *urnti_ptr,
  tdsrrc_RRC_StateIndicator rcvd_state_indicator  
)
{
  /* internal rrc state */
  tdsrrc_state_e_type int_state_indicator = TDSRRC_STATE_DISCONNECTED;


  /* Update U-RNTI */
  if(urnti)
  {
    /* Indicate to MAC that only have a valid U_RNTI, and to use in MAC header */
    tdsrrc_translate_urnti(urnti_ptr, &tdsordered_config_ptr->mac_ul_parms.rnti_info.urnti);
    tdsordered_config_ptr->mac_dl_parms.rnti_info.urnti = 
      tdsordered_config_ptr->mac_ul_parms.rnti_info.urnti;
    
    if((tdsordered_config_ptr->mac_dl_parms.rnti_info.rnti_valid == TDSCRNTI_VALID)||
      (tdsordered_config_ptr->mac_dl_parms.rnti_info.rnti_valid == TDSBOTH_VALID))
    {
      /* CRNTI is already valid - with new URNTI, both are valid now */
      tdsordered_config_ptr->mac_dl_parms.rnti_info.rnti_valid = TDSBOTH_VALID;
      tdsordered_config_ptr->mac_ul_parms.rnti_info.rnti_valid = TDSBOTH_VALID;
    }
    else
    {
      /* CRNTI is NOT valid, with new URNTI, only URNTI is valid */
      tdsordered_config_ptr->mac_dl_parms.rnti_info.rnti_valid = TDSURNTI_VALID;
      tdsordered_config_ptr->mac_ul_parms.rnti_info.rnti_valid = TDSURNTI_VALID;
    }

    /* go inside if check if state is FACH/PCH or URA_PCH */
    if (tdsrrc_RRC_StateIndicator_cell_DCH != rcvd_state_indicator)
    {
      int_state_indicator = 
        tdsrrc_translate_state_indicator_to_state(rcvd_state_indicator);

      if(tdsrrcllc_copy_sccpch_info_from_sib_to_oc_in_connected_mode(
         tdsrrc_get_state(), int_state_indicator)
          == FAILURE)
      {
        TDSRRC_MSG0(MSG_LEGACY_ERROR,"Failure to update OC from SIB");
        return(FAILURE);
      }
    }
  }  /* If new URNTI is present */

  return (SUCCESS);
}

/*===========================================================================
FUNCTION tdsrrcllc_update_crnti_in_oc
DESCRIPTION
This function updates the C-RNTI received in any reconfig message in 
tdsordered_config

DEPENDENCIES
  None.

RETURN VALUE
  None
===========================================================================*/
static void tdsrrcllc_update_crnti_in_oc
(
  uint32 crnti_present,
  ASN1BitStr32 crnti,
  tdsrrc_RRC_StateIndicator rcvd_state_indicator  
)
{
  /* Local C_RNTI value */
  tdsrrc_int_c_rnti_type             local_int_c_rnti;


  /* Update C-RNTI */
  if(crnti_present)
  {
    /* Indicate to MAC that have a valid U_RNTI and C_RNTI */
    tdsrrc_translate_crnti(&crnti, &local_int_c_rnti);
    tdsordered_config_ptr->mac_ul_parms.rnti_info.crnti = (uint16)local_int_c_rnti;
    tdsordered_config_ptr->mac_dl_parms.rnti_info.crnti = (uint16)local_int_c_rnti;
    
    if((tdsordered_config_ptr->mac_dl_parms.rnti_info.rnti_valid == TDSURNTI_VALID)||
      (tdsordered_config_ptr->mac_dl_parms.rnti_info.rnti_valid == TDSBOTH_VALID))
    {
      /* URNTI is already valid - with new CRNTI, both are valid now */
      tdsordered_config_ptr->mac_ul_parms.rnti_info.rnti_valid = TDSBOTH_VALID;
      tdsordered_config_ptr->mac_dl_parms.rnti_info.rnti_valid = TDSBOTH_VALID;
    }
    else
    {
      /* URNTI is NOT valid, with new CRNTI, only CRNTI is valid */
      tdsordered_config_ptr->mac_ul_parms.rnti_info.rnti_valid = TDSCRNTI_VALID;
      tdsordered_config_ptr->mac_dl_parms.rnti_info.rnti_valid = TDSCRNTI_VALID;
    }
  }  /* If new CRNTI present */

}

/*===========================================================================
FUNCTION tdsrrcllc_update_delay_restriction
DESCRIPTION
This function updates the activation time based on delay restriction flag received in the OTA

DEPENDENCIES
  None.

RETURN VALUE
  None
===========================================================================*/
void tdsrrcllc_update_delay_restriction
(
  uint32 act_time_present, 
  uint32 delay_restriction_present,
  tdsrrc_ActivationTime act_time,
  tdsrrc_RRC_StateIndicator rcvd_state_indicator
)
{
  uint8 act_fn_num=0;

  if(act_time_present && delay_restriction_present )
  {
    if((tdsrrc_get_hsdpa_action() == TDSHSDPA_START) || (tdsrrc_get_hsdpa_status() == TDSHSDPA_ACTIVE))
    {
      if((tdsrrc_get_state() == TDSRRC_STATE_CELL_DCH) &&
         (rcvd_state_indicator == tdsrrc_RRC_StateIndicator_cell_DCH))
      {
        act_fn_num = ((256 + (act_time) - tdsordered_config_ptr->sdu_time ) & 0xFF);
        if ( act_fn_num > 128)
  
        {
          TDSRRC_MSG1(MSG_LEGACY_HIGH,"Activation Time is Now!delay restriction falg,activation %d more than current CFN",act_fn_num);
          tdsordered_config_ptr->activation_time = TDSRRCLLC_ACTIVATION_TIME_NOW;
          tdsordered_config_ptr->act_time_type   = TDSL1_ACTIVATION_TIME_NONE;
        }
      }
    }
    else
    {
      TDSRRC_MSG0(MSG_LEGACY_ERROR,"HS not Active,so do not process Delay restriction IE");  
    }
  }
}

/*===========================================================================
FUNCTION rrcrb_update_activation_time
DESCRIPTION
This function updates the activation time received in any reconfig message in 
tdsordered_config

DEPENDENCIES
  None.

RETURN VALUE
  None
===========================================================================*/
static void tdsrrcllc_update_activation_time_in_oc
(
  uint32 act_time_present, 
  tdsrrc_ActivationTime act_time,
  tdsrrc_RRC_StateIndicator rcvd_state_indicator,
  tdsrrc_proc_e_type proc_id
)
{

  uint16 min_act_time = 0;

  if(act_time_present)
  {
    if ((rcvd_state_indicator == tdsrrc_RRC_StateIndicator_cell_FACH) && 
        (tdscurrent_config_ptr->rrc_state_indicator == TDSRRC_STATE_CELL_DCH)) 
    {
      /* Have at least activatin time of 300 milli seconds, so that the
         base station can get RLC L2 Ack for Reconfiguration.
      */ 
      min_act_time = (tdsseq_get_cfn() + 30) & 0xFF;
      if (((256+(act_time)-(tdsseq_get_cfn())) & 0xFF) < 30) 
      {
        tdsordered_config_ptr->activation_time = min_act_time;
      }
      else
      {
        tdsordered_config_ptr->activation_time = (uint16) act_time;
      }

      tdsordered_config_ptr->act_time_type   = TDSL1_ACTIVATION_TIME_CFN;
      if(proc_id != TDSMAX_NUM_OF_PROCEDURES)
      {
      tdsordered_config_ptr->sdu_time        = tdsrrc_cfn_before_decode[proc_id];
      }

      TDSRRC_MSG1(MSG_LEGACY_HIGH,"Activation time is 0x%x",tdsordered_config_ptr->activation_time);
    }
    else
    {
      TDSRRC_MSG1(MSG_LEGACY_MED,"Activation Time is %d",act_time);
      tdsordered_config_ptr->activation_time = (uint16)act_time;
      tdsordered_config_ptr->act_time_type   = TDSL1_ACTIVATION_TIME_CFN;
      if(proc_id != TDSMAX_NUM_OF_PROCEDURES)
      {
        tdsordered_config_ptr->sdu_time        = tdsrrc_cfn_before_decode[proc_id];
      }
    }
  }
  else
  {
    if ((rcvd_state_indicator == tdsrrc_RRC_StateIndicator_cell_FACH) && 
        (tdscurrent_config_ptr->rrc_state_indicator == TDSRRC_STATE_CELL_DCH)) 
    {
      min_act_time = (tdsseq_get_cfn() + 30) & 0xFF;
      tdsordered_config_ptr->activation_time = min_act_time;
      tdsordered_config_ptr->act_time_type   = TDSL1_ACTIVATION_TIME_CFN;
      if(proc_id != TDSMAX_NUM_OF_PROCEDURES)
      {
        tdsordered_config_ptr->sdu_time        = tdsrrc_cfn_before_decode[proc_id];
      }
      TDSRRC_MSG1(MSG_LEGACY_HIGH,"Activation time is 0x%x",tdsordered_config_ptr->activation_time);
    }
    else
    {
      /* Assume that the default is now, i.e. the current SFN */
      TDSRRC_MSG0(MSG_LEGACY_MED,"Activation Time is Now!");
      tdsordered_config_ptr->activation_time = TDSRRCLLC_ACTIVATION_TIME_NOW;
      tdsordered_config_ptr->act_time_type   = TDSL1_ACTIVATION_TIME_NONE;
      /* sdu_time may be used to decide whether TDSL1_CPHY_ACT_TIME_CANCEL_REQ can be sent to L1 afterwards,
       * so it should be updated here even act_time is Now
       */
      if(proc_id != TDSMAX_NUM_OF_PROCEDURES)
      {
        tdsordered_config_ptr->sdu_time        = tdsrrc_cfn_before_decode[proc_id];
      }
    }
  }
}
/*====================================================================
FUNCTION: FIND_TRCH_ID_IN_CONFIG_TRCH_LIST

DESCRIPTION:

DEPENDENCIES:
  None.

RETURN VALUE:
  None.

SIDE EFFECTS:
  None.
====================================================================*/
static boolean tdsrrcllc_find_trch_id_in_config_trch_list
(
  tdsrrc_DL_AddReconfTransChInfoList * dl_trch_add_reconfig_ptr,
  tr_ch_id_type tdstrch_id
)
{
  uint32 num_TrCh = 0;
  boolean found = FALSE;

  while((num_TrCh <= TDSUE_MAX_TRCH) && (dl_trch_add_reconfig_ptr->n > num_TrCh))
  {
    if (dl_trch_add_reconfig_ptr->elem[num_TrCh].dl_transportChannelIdentity == tdstrch_id)
    {
      found = TRUE;
      break;
    }

    num_TrCh++;
  }

  return found;
}


/*====================================================================
FUNCTION: FIND_TRCH_ID_IN_CONFIG_TRCH_LIST_R5

DESCRIPTION:

DEPENDENCIES:
  None.

RETURN VALUE:
  None.

SIDE EFFECTS:
  None.
====================================================================*/
boolean tdsrrcllc_trch_id_in_config_trch_list_r5
(
  tdsrrc_DL_AddReconfTransChInfoList_r5 * dl_trch_add_reconfig_ptr,
  tr_ch_id_type tdstrch_id
)
{
  uint32 idx = 0;
  boolean found = FALSE;
  
  while((idx <= TDSUE_MAX_TRCH) && (dl_trch_add_reconfig_ptr->n > idx))
  {
    if (dl_trch_add_reconfig_ptr->elem[idx].dl_TransportChannelType.t == T_tdsrrc_DL_TrCH_TypeId1_r5_dch)
    {
      if (dl_trch_add_reconfig_ptr->elem[idx].dl_TransportChannelType.u.dch == tdstrch_id)
      {
        found = TRUE;
        break;
      }
    }

    idx++;
  }
  
  return found;
}

